G = graph_from_edges(Directed, [[10,6],[7,6],[8,7],[9,8],[9,10],[6,2],[7,3],[8,1],[9,5],[10,4]])
net = phylogenetic_network(G)
N = cavender_farris_neyman_model(net)
phi = parametrization(N)
H = components_of_kernel(2, phi, show_progress = true)
I = ideal(reduce(vcat, collect(values(H))))

